import{LEVEL,platforms,create,step}from"./cloister-sim.js";const canvas=document.querySelector("#game"),ctx=canvas.getContext("2d"),$=q=>document.querySelector(q);let s=create(),running=false,art={},atlas,last=0,acc=0;const held=new Set,pulse={},map={KeyA:"left",ArrowLeft:"left",KeyD:"right",ArrowRight:"right",Space:"jump",KeyW:"jump",ArrowUp:"jump",KeyS:"crouch",ArrowDown:"crouch",KeyJ:"attack",KeyX:"attack",KeyE:"interact"},load=path=>new Promise((ok,no)=>{const i=new Image;i.onload=()=>ok(i);i.onerror=()=>no(Error(path));i.src=path});function keyed(im){const c=document.createElement("canvas"),g=c.getContext("2d",{willReadFrequently:true});c.width=im.width;c.height=im.height;g.drawImage(im,0,0);const d=g.getImageData(0,0,c.width,c.height),a=d.data;for(let i=0;i<a.length;i+=4){const excess=Math.min(a[i],a[i+2])-a[i+1];if(excess>80)a[i+3]=0;else if(excess>20)a[i+3]=255*(80-excess)/60}g.putImageData(d,0,0);return c}function start(){running=true;$("#start-overlay").classList.add("hidden");canvas.focus()}$("#enter").onclick=start;$("#reset").onclick=()=>{s=create();start()};addEventListener("keydown",e=>{if(document.activeElement!==canvas)return;const a=map[e.code];if(a){e.preventDefault();held.add(a);if(!e.repeat)pulse[a]=true}});addEventListener("keyup",e=>held.delete(map[e.code]));for(const b of document.querySelectorAll("[data-control]")){b.onpointerdown=e=>{e.preventDefault();start();const a=b.dataset.control;held.add(a);pulse[a]=true;b.setPointerCapture(e.pointerId)};for(const n of["pointerup","pointercancel","lostpointercapture"])b.addEventListener(n,()=>held.delete(b.dataset.control))}function input(){return{left:held.has("left"),right:held.has("right"),crouch:held.has("crouch"),jump:!!pulse.jump,attack:!!pulse.attack,interact:!!pulse.interact}}
function platform(p){ctx.fillStyle="#1b2730";ctx.fillRect(p.x,p.y,p.w,p.h??150);ctx.save();ctx.beginPath();ctx.rect(p.x,p.y,p.w,70);ctx.clip();for(let x=p.x;x<p.x+p.w;x+=240)ctx.drawImage(art.cap,x,p.y,240,60);ctx.restore();ctx.strokeStyle="#9baaa4";ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+p.w,p.y);ctx.stroke()}function hero(){const f=atlas.frames[s.attack?(s.attack>.24?5:s.attack>.1?6:7):0],scale=144/418;ctx.save();ctx.translate(s.x,s.y);ctx.scale(s.facing,1);ctx.drawImage(art.hero,f.x,f.y,f.width,f.height,-f.pivotX*scale,-f.pivotY*scale,f.width*scale,f.height*scale);ctx.restore()}
function draw(){ctx.fillStyle="#0b131b";ctx.fillRect(0,0,1280,720);const fog=ctx.createLinearGradient(0,0,0,720);fog.addColorStop(0,"#18242d");fog.addColorStop(1,"#081017");ctx.fillStyle=fog;ctx.fillRect(0,0,1280,720);ctx.save();ctx.translate(-s.camera*.18,0);ctx.globalAlpha=.42;for(let x=80;x<5000;x+=620)ctx.drawImage(art.arch,x,125,520,520);ctx.restore();ctx.save();ctx.translate(-s.camera,0);for(const p of platforms)platform(p);for(let x=360;x<4200;x+=760)ctx.drawImage(art.pier,x,280,210,330);ctx.drawImage(art.lever,s.leverOn?1024:0,0,1024,1024,LEVEL.lever-45,500,90,90);ctx.drawImage(art.grate,LEVEL.gate-65,s.leverOn?275:438,130,162);if(!s.vialTaken)ctx.drawImage(art.vial,1868,520+Math.sin(s.time*3)*5,64,64);const e=s.enemy;if(e.hp>0){ctx.fillStyle="#6b7478";ctx.fillRect(e.x-22,e.y-120,44,120);ctx.fillStyle="#c5a36b";ctx.fillRect(e.x-45,e.y-93,90,8);ctx.fillStyle="#9a564d";ctx.fillRect(e.x-24,e.y-145,48*(e.hp/3),5)}hero();ctx.fillStyle="#d9bc82";ctx.font="17px Georgia";for(const [x,t]of[[180,"I · BROKEN ARCADE"],[1280,"II · VIAL LEDGE"],[2140,"III · LEVER COURT"],[3220,"IV · GATE WALK"]])ctx.fillText(t,x,220);ctx.fillText("E · PULL",LEVEL.lever-35,475);ctx.restore();$("#health").textContent="♥".repeat(s.hp)+"♡".repeat(5-s.hp);$("#progress").value=s.x/LEVEL.width*100;$("#notice").textContent=s.noticeTime?s.notice:"";$("#status").textContent=s.complete?"STAGE BLOCKOUT COMPLETE":s.x<1100?"BROKEN ARCADE":s.x<2100?"VIAL LEDGE":s.x<3000?"LEVER COURT":"GATE WALK"}
function tick(now){if(running){acc+=Math.min((now-last)/1000,.1);while(acc>=1/60){step(s,input());for(const k of Object.keys(pulse))delete pulse[k];acc-=1/60}}last=now;draw();requestAnimationFrame(tick)}try{[art.arch,art.pier,art.cap,art.lever,art.grate,art.vial,art.hero]=await Promise.all(["art/contributions/08-ruined-cloister/v001/exports/cloister-arch-span-v001.png","art/contributions/08-ruined-cloister/v001/exports/cloister-pier-v001.png","art/contributions/world-02-ruined-cloister/v001/exports/platform-cap-v001.png","art/contributions/15-mechanisms/v001/exports/lever-v001.png","art/contributions/15-mechanisms/v003/exports/grate-v001.png","art/contributions/14-pickups-and-relics/v001/exports/healing-vial-v001.png","art/production/bellwarden/bellwarden-pilot-v001.png"].map(load));atlas=await fetch("art/production/bellwarden/bellwarden-pilot-v001.json").then(r=>r.json());art.hero=keyed(art.hero);requestAnimationFrame(tick)}catch(e){$("#notice").textContent="Stage art failed to load: "+e.message}
